R=C=10; seen=set(); comps=[]
for r in range(1,R):
 for c in range(C):
  v=grid[r][c]
  if v and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c)); comp=[]
   while st:
    a,b=st.pop();comp.append((a,b))
    for p,q in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 1<=p<R and 0<=q<C and grid[p][q]==v and (p,q) not in seen: seen.add((p,q));st.append((p,q))
   comps.append((v,comp))
comps=sorted(comps,key=lambda x:min(r for r,c in x[1]))
occ={(0,c):2 for c in range(C)}; out=[[0]*C for _ in range(R)];out[0]=[2]*C
for v,co in comps:
 d=0
 while all((r-d-1,c) not in occ for r,c in co): d+=1
 for r,c in co: out[r-d][c]=v;occ[r-d,c]=v
out
